  const panels = [];
  for (const [sa, sb] of X.TS){ const m = Math.max(4, Math.round((sb - sa)/8.95/2)*2);
    for (let j = 0; j < m; j++) panels.push({a:sa + (sb - sa)*j/m, b:sa + (sb - sa)*(j + 1)/m, mid:j < m/2 ? 1 : -1, kind:'deck', end:j === m - 1}); }
