      const Lw = [node(f, c - sw*(RS_TRUSS_HW - 0.7), zl - 0.08), node(f, f.wB - sw*6.5, zl - 0.08), node(f, f.wB - sw*6.5, zl - 1.6), node(f, c - sw*(RS_TRUSS_HW - 0.7), zl - 1.6)];
      if (pu){ q4(oc, pu[0], pu[1], U[1], U[0]); q4(od, pu[3], pu[2], U[2], U[3]); q4(oc, pu[1], pu[2], U[2], U[1]);
        q4(oc, pl[0], pl[1], Lw[1], Lw[0]); q4(od, pl[3], pl[2], Lw[2], Lw[3]); q4(oc, pl[0], pl[3], Lw[3], Lw[0]); }
