    for (let s = Math.ceil(g0/30)*30; s < g1; s += 30){ const f = F.at(s); if (!stacked(f)) continue; const q = F.P(f, f.wB); L.lamp2.push(q[0], Z_RSU(s) - 2.4, q[1]); }
